      "source_locator": "openalex-request:836584535ac5e307a1453d9a396b2ef4a9029ea3952d4d30699ec939e8cc9368#results[35];abstract[1011:1186]",
      "source_url": "https://openalex.org/W4409366437",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "More specifically, inspired by the observation that the composed recognition models could account for the differences across sub-classes, we first propose to impose the embedding alignment between the composed and disentangled recognition to incorporate sub-class discrimination at the feature level.",
      "id": "evidence:topic:5b42da31560d4c67a16f783d3c27e2eb73b01f4f8cec076acfad16d3cc67e6e9",
      "kind": "inferred_topic",
