      "retrieved_at": "2026-11-07T20:26:27.653183Z",
      "source_locator": "openalex-request:967312d65e29b11404dd4ab55e6c56d8baa4e276359a63ad665ff9a1ea307969#results[29];abstract[711:1011]",
      "source_url": "https://openalex.org/W4382240738",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Prompt learning has emerged as a promising method for adapting pre-trained visual-language models (VLMs) to a range of downstream tasks.",
      "id": "evidence:topic:5b91ea28c12fbcae63869730a0c484354b53a5b0ef3a9f9a0e6ed07d3b8b555a",
      "kind": "inferred_topic",
