      "source_url": "https://openalex.org/W4382458598",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Specifically, we propose to use complementary subgraphs as latent diffusion conditions and self-supervised targets respectively during pre-training.",
      "id": "evidence:topic:5df58eff7920e9a0f8280de70ad8011bc6c1984c382c13f1dd390346d61a9d6a",
      "kind": "inferred_topic",
      "raw_sha256": "43f4689046dc4c434e5c5f13bfcaa572c4f983e897a3a1384baeb52584ed6611",
      "retrieved_at": "2026-11-07T20:28:59.325095Z",
      "source_locator": "openalex-request:c574330d8f606e5c161aadedc3bde039deb6597cedf512738cd17ae9bea8967d#results[42];abstract[1118:1266]",
      "source_url": "https://openalex.org/W4409365498",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
