      "id": "evidence:topic:5f92fa97c2425ac38e947abc088a88fbbd7a457728ba3a9e47c443e087fab051",
      "kind": "inferred_topic",
      "raw_sha256": "f65ae2c1c9c75b44ce50d395549157cd4218c57d03fdd1d387f96a57f82da941",
      "retrieved_at": "2026-11-07T20:30:39.783182Z",
