      "source_url": "https://openalex.org/W4409370097",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "We introduce Perceiving Stroke-Semantic Context (PerSec), a new approach to self-supervised representation learning tailored for Scene Text Recognition (STR) task.",
      "id": "evidence:topic:7da4c4a541404a23ec43f8e76eb321ec615570561ad15ea157b72ea2b63f5a4f",
