      "source_url": "https://openalex.org/W4283805255",
      "support_edge_ids": [],
      "support_paper_ids": []
    },
    {
      "excerpt": "Recent efforts further demonstrate the potential of SNNs in supervised learning by introducing approximated backpropagation (BP) methods.",
      "id": "evidence:topic:7feb20a2af56a2495c22e477883f66b678f58bf0b537458500b33b27c843e601",
      "kind": "inferred_topic",
      "raw_sha256": "b19fab072a2045d9ae91d7e4ff36a1cbefd6d419d220782f97949bde2848110f",
      "retrieved_at": "2026-11-07T20:25:06.903484Z",
