      "raw_sha256": "d0d3e825b1695ae7099bfb9101d7bd7932f48c47fe7ec330556c2a6feee841f6",
      "retrieved_at": "2026-11-07T20:28:36.577107Z",
      "source_locator": "openalex-request:01cbc20e63568c70ae89678bf61aa8e991a961156936cb47eab2f941288645a9#results[32]",
      "source_url": "https://openalex.org/W4409367743",
